import { promises as fs } from "node:fs";
import path from "node:path";
import { randomBytes } from "node:crypto";
import { env } from "../config/env";
import { logger } from "../lib/logger";

/**
 * Single-redemption (or N-redemption) signup tokens generated by an owner from
 * `OwnerDesk` and consumed by `/v1/auth/register`. Designed to live alongside
 * `registeredUsers.ts` — same JSON-on-disk + in-memory pattern.
 *
 * A code can either pin a specific role (e.g. "this code mints a controller")
 * or fall back to `REGISTRATION_DEFAULT_ROLE`. Codes track `uses` against
 * `maxUses`; once exhausted the next consume call returns `expired`.
 */

const ROLE_VALUES = ["guest", "pilot", "controller", "mod", "supermod", "owner"] as const;
type StoredRole = (typeof ROLE_VALUES)[number];

function isStoredRole(value: unknown): value is StoredRole {
  return typeof value === "string" && (ROLE_VALUES as readonly string[]).includes(value);
}

export type InviteCode = {
  code: string;
  /** Role minted on successful redemption. `null` means use REGISTRATION_DEFAULT_ROLE. */
  role: StoredRole | null;
  /** Owner / mod userId who minted the code. */
  createdByUserId: string;
  createdAt: string;
  /** Hard cap on how many accounts this code can mint. */
  maxUses: number;
  /** How many accounts have been minted. `uses >= maxUses` means exhausted. */
  uses: number;
  /** Optional expiry. Codes with no expiry live until consumed or revoked. */
  expiresAt: string | null;
  /** Optional human-readable label (e.g. "KSP forum thread #1234"). Shown in OwnerDesk. */
  label: string;
};

const codes = new Map<string, InviteCode>();
let loaded = false;
let writeQueue: Promise<void> = Promise.resolve();

function resolveStorePath(): string {
  return path.resolve(process.cwd(), env.INVITE_CODES_PATH);
}

async function ensureDir(filePath: string): Promise<void> {
  await fs.mkdir(path.dirname(filePath), { recursive: true });
}

export async function loadInviteCodes(): Promise<void> {
  if (loaded) return;
  loaded = true;
  const filePath = resolveStorePath();
  let raw: string;
  try {
    raw = await fs.readFile(filePath, "utf8");
  } catch (err) {
    const e = err as NodeJS.ErrnoException;
    if (e.code === "ENOENT") {
      logger.info({ filePath }, "Invite-codes store does not exist yet; starting empty.");
      return;
    }
    logger.error({ err, filePath }, "Failed to read invite-codes store; starting empty.");
    return;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    logger.error({ err, filePath }, "Invite-codes store is not valid JSON; refusing to overwrite, starting empty.");
    return;
  }
  if (!Array.isArray(parsed)) {
    logger.error({ filePath }, "Invite-codes store must be a JSON array; starting empty.");
    return;
  }
  for (const entry of parsed) {
    if (!entry || typeof entry !== "object") continue;
    const e = entry as Record<string, unknown>;
    const code = typeof e.code === "string" ? e.code.trim() : "";
    if (!code) continue;
    const role = isStoredRole(e.role) ? e.role : e.role === null ? null : null;
    const createdByUserId = typeof e.createdByUserId === "string" ? e.createdByUserId : "";
    const createdAt = typeof e.createdAt === "string" ? e.createdAt : new Date().toISOString();
    const maxUses = typeof e.maxUses === "number" && Number.isFinite(e.maxUses) && e.maxUses > 0 ? Math.floor(e.maxUses) : 1;
    const uses = typeof e.uses === "number" && Number.isFinite(e.uses) && e.uses >= 0 ? Math.floor(e.uses) : 0;
    const expiresAt = typeof e.expiresAt === "string" ? e.expiresAt : null;
    const label = typeof e.label === "string" ? e.label : "";
    codes.set(code, { code, role, createdByUserId, createdAt, maxUses, uses, expiresAt, label });
  }
  logger.info({ filePath, count: codes.size }, "Invite-codes store loaded.");
}

async function flushToDisk(): Promise<void> {
  const filePath = resolveStorePath();
  const json = JSON.stringify(Array.from(codes.values()), null, 2);
  const tmpPath = `${filePath}.tmp-${randomBytes(4).toString("hex")}`;
  try {
    await ensureDir(filePath);
    await fs.writeFile(tmpPath, json, { encoding: "utf8", mode: 0o600 });
    await fs.rename(tmpPath, filePath);
  } catch (err) {
    logger.error({ err, filePath }, "Failed to persist invite-codes store.");
    try {
      await fs.unlink(tmpPath);
    } catch {
      /* tmp file may not exist */
    }
  }
}

function queueFlush(): Promise<void> {
  writeQueue = writeQueue.then(flushToDisk, flushToDisk);
  return writeQueue;
}

function newCode(): string {
  // 9 bytes → 18 hex chars (~72 bits of entropy). Easy to copy/paste, hard to
  // brute force, and short enough to read aloud on Discord without losing
  // your audience. Lowercased for case-insensitive matching at consume time.
  return randomBytes(9).toString("hex");
}

export type CreateInviteRequest = {
  createdByUserId: string;
  role?: StoredRole | null;
  maxUses?: number;
  expiresAt?: string | null;
  label?: string;
};

export async function createInviteCode(req: CreateInviteRequest): Promise<InviteCode> {
  if (!loaded) {
    await loadInviteCodes();
  }
  let code = newCode();
  // Vanishingly small collision risk, but be tidy: regenerate if we hit one.
  let attempts = 0;
  while (codes.has(code) && attempts < 4) {
    code = newCode();
    attempts += 1;
  }
  const row: InviteCode = {
    code,
    role: req.role ?? null,
    createdByUserId: req.createdByUserId,
    createdAt: new Date().toISOString(),
    maxUses: req.maxUses && req.maxUses > 0 ? Math.floor(req.maxUses) : 1,
    uses: 0,
    expiresAt: req.expiresAt ?? null,
    label: req.label ?? ""
  };
  codes.set(code, row);
  await queueFlush();
  return row;
}

export type ConsumeResult =
  | { ok: true; role: StoredRole | null }
  | { ok: false; reason: "unknown" | "expired" | "exhausted" };

/**
 * Atomically increment `uses` if the code is valid + has capacity left. Caller
 * decides whether to fall back to REGISTRATION_DEFAULT_ROLE when `role` is null.
 */
export async function consumeInviteCode(rawCode: string): Promise<ConsumeResult> {
  if (!loaded) {
    await loadInviteCodes();
  }
  const code = rawCode.trim().toLowerCase();
  const row = codes.get(code);
  if (!row) {
    return { ok: false, reason: "unknown" };
  }
  if (row.expiresAt && new Date(row.expiresAt).getTime() < Date.now()) {
    return { ok: false, reason: "expired" };
  }
  if (row.uses >= row.maxUses) {
    return { ok: false, reason: "exhausted" };
  }
  row.uses += 1;
  await queueFlush();
  return { ok: true, role: row.role };
}

export function listInviteCodes(): InviteCode[] {
  return Array.from(codes.values()).sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1));
}

export async function revokeInviteCode(rawCode: string): Promise<boolean> {
  if (!loaded) {
    await loadInviteCodes();
  }
  const code = rawCode.trim().toLowerCase();
  const removed = codes.delete(code);
  if (removed) {
    await queueFlush();
  }
  return removed;
}
